    inv_open IV;
    let B := fresh "B" in pose proof BL_ok as B; unfold BL in B;
    assert (RSTK' : rng RNG (bv_unsigned sp + -2320) 2320) by (eapply rng_sub'; [exact RSTK| lia]);
    hide_sec.

